//! Checks traced outlines against ImageJ's Wand, vertex for vertex.
//!
//! Fixture generated by `parity/java/WandOutline.java` via `./parity/record.sh`,
//! recorded through `Wand.autoOutline(x, y, 0.5, +inf, Wand.FOUR_CONNECTED)` —
//! the mode `RoiLabeling.getFilledPolygonROIs` passes at
//! `WatershedCellDetection`'s line 870, which is the trace whose polygons become
//! `PathObject` geometry. Needs no slide.
//!
//! The companion of `parity_filled_regions.rs`, which pins the same boundaries
//! from the other side: that one compares the **mask** each polygon rasterises
//! to, this one compares the **polygon**. `regions.rs` says why the mask was
//! done first — it is what every later stage consumes — and `ROADMAP.md` §1.5b
//! step 4 is why the polygon is needed too: exporting geometry wants a ring, and
//! `DIVERGENCES.md` D-008 compares the area of a *smoothed* one, which cannot
//! exist until the unsmoothed one does.
//!
//! # Compared up to rotation, and that is a named gap
//!
//! Every vertex, the length and the winding are pinned; **where the ring starts
//! is not**. That is deliberate and it is not a tolerance quietly widened to get
//! a pass — ImageJ's offset is not reproducible from the recorded output.
//! `single_pixel` and `square` are listed from the region's bottom-right corner,
//! which looks like a rule, and then `ell` is listed from `(2, 3)`, which is not
//! a corner of its seed pixel at all. The offset falls out of where `Wand`'s own
//! scan begins.
//!
//! The winding *is* compared, because the direction decides the sign of a
//! shoelace area and D-008 is an area comparison. What consumes these lists is
//! smoothing and an area, and neither depends on which vertex is written first.
//! If something later does, this comment is where to look.

use qupath_watershed::{Outline, outline_mask};

const FIXTURE: &str = include_str!("../../../parity/fixtures/WandOutline.json");

/// One `{ ... }` case block, in file order.
fn cases(fixture: &str) -> Vec<&str> {
    fixture
        .split("\n    {\n")
        .skip(1)
        .map(|block| block.split("\n    }").next().expect("a case block"))
        .collect()
}

/// The text of one field.
fn text<'a>(block: &'a str, key: &str) -> &'a str {
    let needle = format!("\"{key}\": ");
    let at = block
        .find(&needle)
        .unwrap_or_else(|| panic!("no {key} in {block}"))
        + needle.len();
    let rest = &block[at..];
    if let Some(body) = rest.strip_prefix('"') {
        let end = body.find('"').expect("an unterminated string");
        return &body[..end];
    }
    let end = rest.find([',', '\n']).unwrap_or(rest.len());
    rest[..end].trim()
}

fn number(block: &str, key: &str) -> usize {
    text(block, key).parse().expect("an integer")
}

/// An `[...]` array of integers named `key`.
fn array(block: &str, key: &str, from: usize) -> (Vec<i32>, usize) {
    let needle = format!("\"{key}\": [");
    let open = block[from..].find(&needle).expect(&needle) + from + needle.len();
    let close = block[open..].find(']').expect("an unterminated array") + open;
    let body = &block[open..close];
    let values = if body.trim().is_empty() {
        Vec::new()
    } else {
        body.split(',')
            .map(|value| value.trim().parse().expect("an integer"))
            .collect()
    };
    (values, close)
}

/// The outlines QuPath recorded for one case, in the order it found them.
fn recorded(block: &str) -> Vec<Outline> {
    let mut out = Vec::new();
    let mut at = block.find("\"outlines\": [").expect("an outlines array");
    while let Some(found) = block[at..].find("{\"startX\": ") {
        at += found;
        let (xs, after_x) = array(block, "x", at);
        let (ys, after_y) = array(block, "y", at);
        assert_eq!(xs.len(), ys.len(), "an outline with mismatched coordinates");
        assert_eq!(
            xs.len(),
            number(&block[at..], "npoints"),
            "npoints disagrees with the coordinates recorded beside it"
        );
        out.push(Outline {
            points: xs.into_iter().zip(ys).collect(),
        });
        at = after_x.max(after_y);
    }
    out
}

/// The mask of one case, as bytes.
fn mask(block: &str) -> Vec<u8> {
    let (values, _) = array(block, "mask", 0);
    values
        .into_iter()
        .map(|value| u8::try_from(value).expect("a 0 or 1"))
        .collect()
}

/// Whether two rings are the same cycle, allowing a different starting vertex.
///
/// Rotation only — **not** reversal, so a ring wound the other way fails here as
/// it should.
fn same_ring(ours: &[(i32, i32)], theirs: &[(i32, i32)]) -> bool {
    if ours.len() != theirs.len() {
        return false;
    }
    if ours.is_empty() {
        return true;
    }
    (0..ours.len()).any(|offset| {
        (0..ours.len()).all(|index| ours[(offset + index) % ours.len()] == theirs[index])
    })
}

#[test]
fn every_outline_matches_vertex_for_vertex() {
    let blocks = cases(FIXTURE);
    assert!(!blocks.is_empty(), "the fixture has no cases");

    for block in &blocks {
        let name = text(block, "name");
        let width = number(block, "width");
        let expected = recorded(block);
        let found = outline_mask(&mask(block), width);

        assert_eq!(
            found.len(),
            expected.len(),
            "{name}: traced {} outlines, QuPath found {}",
            found.len(),
            expected.len()
        );
        for (index, (ours, theirs)) in found.iter().zip(&expected).enumerate() {
            assert!(
                same_ring(&ours.points, &theirs.points),
                "{name}: outline {index} is not the Wand's ring\n  ours:   {:?}\n  theirs: {:?}",
                ours.points,
                theirs.points
            );
        }
    }
}

/// Every case in the fixture is exercised, and the count is pinned.
///
/// A parser that silently found no cases would make the test above pass by
/// running nothing, which is how a parity check stops being one.
#[test]
fn the_fixture_carries_the_cases_it_is_supposed_to() {
    let blocks = cases(FIXTURE);
    assert_eq!(blocks.len(), 9, "the recorded case count changed");

    let names: Vec<&str> = blocks.iter().map(|block| text(block, "name")).collect();
    for expected in [
        "single_pixel",
        "square",
        "bar",
        "ell",
        "plus",
        "donut",
        "diagonal_touch",
        "edge",
        "staircase",
    ] {
        assert!(
            names.contains(&expected),
            "{expected} is not in the fixture"
        );
    }
}

/// The three conventions the fixture settled, asserted as facts.
///
/// The test above would keep passing if the fixture were re-recorded against a
/// different mode or a different ImageJ, because it compares two things that
/// moved together. These pin the *values*, so such a re-recording is visible.
#[test]
fn the_conventions_are_the_ones_that_were_recorded() {
    let blocks = cases(FIXTURE);
    let case = |name: &str| {
        *blocks
            .iter()
            .find(|block| text(block, "name") == name)
            .unwrap_or_else(|| panic!("no {name} case"))
    };

    // Vertices on pixel corners, not centres. A single pixel at (1, 1) spans
    // the corners 1..2 in both axes.
    let single = recorded(case("single_pixel"));
    assert_eq!(single.len(), 1);
    assert_eq!(single[0].points, vec![(2, 2), (1, 2), (1, 1), (2, 1)]);

    // Only corners are emitted: a four-pixel bar is four points, not six.
    let bar = recorded(case("bar"));
    assert_eq!(
        bar[0].len(),
        4,
        "a collinear run emitted intermediate points"
    );

    // A hole is filled, not traced: a ring is its outer rectangle.
    let donut = recorded(case("donut"));
    assert_eq!(donut.len(), 1, "the hole was traced as a second outline");
    assert_eq!(donut[0].len(), 4, "the ring is not its outer rectangle");

    // Four-connected: a diagonal touch is two regions, not one.
    let touch = recorded(case("diagonal_touch"));
    assert_eq!(
        touch.len(),
        2,
        "a diagonal touch merged, which is the eight-connected trace"
    );
}

/// An unsmoothed outline of a filled region encloses exactly its pixels.
///
/// Not a QuPath comparison — a self-check on the geometry, and the reason it is
/// here is D-008. That entry turns on the area of a *smoothed* polygon differing
/// from the enclosed pixel count; this establishes the baseline it differs
/// *from*, so when smoothing lands the change is attributable to the smoothing.
///
/// The sign is checked too. It is **positive** for every case: the walk keeps
/// the interior on its right, which winds clockwise on screen, and clockwise
/// with `y` increasing downwards gives a positive shoelace sum — the opposite of
/// the textbook convention, which assumes `y` goes up. D-008's comparison is on
/// an area whose sign a reversed winding would flip, so this is pinned rather
/// than taken as read.
#[test]
fn the_area_of_an_outline_is_its_pixel_count() {
    for block in cases(FIXTURE) {
        let name = text(block, "name");
        let width = number(block, "width");
        let bytes = mask(block);
        let found = outline_mask(&bytes, width);

        // `donut` is the one case where the two legitimately differ: the Wand
        // fills the hole, so the outline encloses a pixel the mask does not
        // carry. That is the convention, not a defect.
        if name == "donut" {
            let area = found[0].double_signed_area().abs();
            assert_eq!(
                area,
                2 * 9,
                "the filled ring should enclose all nine pixels"
            );
            continue;
        }

        let pixels =
            i64::try_from(bytes.iter().filter(|&&byte| byte != 0).count()).expect("a small mask");
        let area: i64 = found
            .iter()
            .map(|outline| {
                let doubled = outline.double_signed_area();
                assert!(
                    doubled > 0,
                    "{name}: the walk wound the other way, which flips a shoelace area"
                );
                doubled.abs()
            })
            .sum();
        assert_eq!(
            area,
            2 * pixels,
            "{name}: enclosed area is not the pixel count"
        );
    }
}
